import { Scene, Mesh } from "three/webgpu";
import { DirectionalLight, AmbientLight, Vector3, Color } from "three/webgpu";
import { BoxGeometry, PlaneGeometry, MeshStandardMaterial } from "three/webgpu";
import { lookAtCamera, startTask, srgb, boxMesh } from "@mtek/benchmarks/baseline-support";

void startTask(() => {
  const scene = new Scene();
  scene.background = srgb("#0b0d12");

  // Camera setup
  const camera = lookAtCamera({
    position: [2.5, 2.5, 5],
    target: [0, 0, 0],
    fovY: 0.9,
    near: 0.1,
    far: 1000
  });

  // Cube (non-metallic, base colour #c8a27a, roughness 0.8)
  const cubeMaterial = new MeshStandardMaterial({
    color: srgb("#c8a27a"),
    roughness: 0.8,
    metalness: 0
  });
  const cubeGeometry = new BoxGeometry(2.0, 2.0, 2.0);
  const cube = new Mesh(cubeGeometry, cubeMaterial);
  cube.name = "Cube";
  scene.add(cube);

  // Floor (10x10, one-sided, facing up, at y = -1, base colour #8a929c, roughness 0.9)
  const floorMaterial = new MeshStandardMaterial({
    color: srgb("#8a929c"),
    roughness: 0.9,
    metalness: 0,
    side: 1  // FrontSide (default, but explicit for clarity)
  });
  const floorGeometry = new PlaneGeometry(10, 10);
  const floor = new Mesh(floorGeometry, floorMaterial);
  floor.name = "Floor";
  floor.position.y = -1;
  floor.rotation.x = -Math.PI / 2; // Rotate to lie flat facing +Y
  scene.add(floor);

  // Directional light (Sun)
  // Direction: (0, -0.6, -0.8), normalized it's already close to unit
  const lightDirection = new Vector3(0, -0.6, -0.8).normalize();
  // For a Lambertian surface facing the light squarely to render as white,
  // intensity should be pi (since outgoing radiance = albedo * E / pi)
  const sunIntensity = Math.PI;
  const sun = new DirectionalLight(new Color(1, 1, 1), sunIntensity);
  sun.name = "Sun";
  sun.position.copy(lightDirection.multiplyScalar(10)); // Place at distance along the direction
  sun.target.position.set(0, 0, 0);
  scene.add(sun);
  scene.add(sun.target); // Ensure target is in scene

  // Ambient light (10% of directional light strength)
  const ambientIntensity = sunIntensity * 0.1;
  const ambient = new AmbientLight(new Color(1, 1, 1), ambientIntensity);
  scene.add(ambient);

  return {
    scene,
    camera,
    clearColor: "#0b0d12"
  };
});
