  const smooth = new Mesh(geometry, smoothMaterial);
  smooth.name = "Smooth";
  smooth.position.set(2, 0, -2);
  smooth.rotation.x = -Math.PI / 2;
  scene.add(smooth);

  return {
    scene,
    camera: lookAtCamera({
      position: [0, 11, 3],
      target: [0, 0, 0],
      fovY: 0.72,
      near: 0.1,
      far: 1000,
    }),
    clearColor: "#1b2430",
  };
});
