    scene,
    camera: orthographicCamera({ position: [0, 0, 10], target: [0, 0, 0], height: 12.8 }),
    clearColor: "#202020",
    update(dt: number) {
      if (state === "running") {
        elapsedTime += dt;
        if (elapsedTime >= runDuration) {
          state = "done";
          beacon.material.color.setStyle("#22c55e");
        }
      }
    },
