    direction: vec3(0.0, 0.0, -1.0);
    projection: Orthographic {
      height: 12.8;
      near: 0.1;
      far: 1000.0;
    };
  }

  entity Track {
    position: vec3(0.0, -1.0, 0.0);
    shape: Box {
      size: vec3(12.0, 0.2, 0.2);
    };
    material: TrackMaterial;
  }

  entity Runner {
    position: vec3(-5.0, 0.0, 0.0);
    shape: Box {
      size: vec3(1.0, 1.0, 0.5);
    };
    material: RunnerMaterial;
  }

  on key_down(Key.Space) {
    running = !running;
  }

  on frame {
    if (running) {
      runnerX = runnerX + (RUNNER_SPEED * frame.delta);

      if (runnerX >= WRAP_RIGHT) {
        runnerX = runnerX - WRAP_WIDTH;
      }
    }

    Runner.position = vec3(runnerX, 0.0, 0.0);
  }
}
