// Custom material for color sweeping effect
material Sweep {
  param time: f32;

  fn fragment(input: SurfaceInput) -> color {
    // Get x coordinate in object space (runs from -2 to 2)
    let x = input.position.x;

    // Compute the weight: w = 0.5 + 0.5 * sin(0.8 * x + t)
    let w = 0.5 + 0.5 * sin(0.8 * x + time);

    // Colors in sRGB
    let colorA = #1a237e;
    let colorB = #ffb300;

    // Convert from sRGB to linear
    let linearA = color.linear(colorA);
    let linearB = color.linear(colorB);

    // Blend in linear space: (1 - w) * A + w * B
    let blended = (1.0 - w) * linearA + w * linearB;

    // Return as-is (already in linear, will be displayed as linear)
    return blended;
  }
}

