// Entry module: declare the scene Demo here.

const BALL_MATERIAL = material {
  param base_color: color;
  param metalness: f32;
  param roughness: f32;

  fragment(input: SurfaceInput) -> color {
    return lighting.pbr(
      input,
      base_color,
      metalness,
      roughness
    );
  };
};

const FLOOR_MATERIAL = material {
  param base_color: color;
  param metalness: f32;
  param roughness: f32;

