    }
  });

  host.onKeyDown("Backspace", () => {
    if (pips.length > 0) {
      const pip = pips.pop();
      if (pip) {
        scene.remove(pip);
      }
    }
  });

  host.onKeyDown("Enter", () => {
    for (const pip of pips) {
      scene.remove(pip);
