import { Scene, Mesh, DirectionalLight, AmbientLight, MeshStandardMaterial, BoxGeometry, PlaneGeometry } from "three/webgpu";
import { srgb, lookAtCamera, startTask } from "@mtek/benchmarks/baseline-support";

void startTask(() => {
  const scene = new Scene();

  // Set clear color
  const clearColor = "#0b0d12";

  // Create camera
  const camera = lookAtCamera({
    position: [2.5, 2.5, 5],
    target: [0, 0, 0],
    fovY: 0.9,
    near: 0.1,
    far: 1000
  });

  // Create cube
  const cubeGeometry = new BoxGeometry(2.0, 2.0, 2.0);
  const cubeMaterial = new MeshStandardMaterial({
    color: srgb("#c8a27a"),
    roughness: 0.8,
    metalness: 0
