// Custom material for color sweep effect
material Sweep {
  param time: f32;

  fn fragment(input: SurfaceInput) -> color {
    // Get x coordinate in object space (ranges from -2 to 2 for the 4-wide box)
    let x = input.position.x;

    // Compute w = 0.5 + 0.5 * sin(0.8 * x + t)
    let w = 0.5 + 0.5 * sin(0.8 * x + time);

    // Define colors in sRGB
    let colorA_srgb = color.srgb(#1a237e);
    let colorB_srgb = color.srgb(#ffb300);

    // Convert to linear
    let colorA_linear = color.linear(colorA_srgb);
    let colorB_linear = color.linear(colorB_srgb);

    // Blend in linear space
    let blended = (1.0 - w) * colorA_linear + w * colorB_linear;

    // Return as-is (already linear)
    return blended;
  }
}

// Scene definition
scene Demo {
  // Clear color: #202020
  clear_color: #202020;

  // Camera at (0, 0, 6) looking at origin
  // Perspective: vFOV 0.9 rad, near 0.1, far 1000
  camera Main {
    position: vec3(0.0, 0.0, 6.0);
    projection: Perspective {
      vertical_fov: 0.9;
      near_plane: 0.1;
      far_plane: 1000.0;
    };
  }

  // State to track elapsed time
  state {
    elapsed_time: f32 = 0.0;
  }

  // Update elapsed time each frame
  on frame {
    self.elapsed_time = self.elapsed_time + frame.delta;
  }

  // Box panel at (0.4, 0, 0), 4 wide, 2 high, 0.2 deep
  entity Panel {
    position: vec3(0.4, 0.0, 0.0);
    mesh: Box {
      size: vec3(4.0, 2.0, 0.2);
    };
    material: Sweep {
      time: self.elapsed_time;
    };
  }
}
